    # A global's initializer can read another global; the order is a depth-first walk that puts
    # every global after the globals it reads.
    order = LinkedHashSet{GlobalBuilder}()

    function dfs(gb::GlobalBuilder)
        instructions = build(gb.initializer)
        for i in instructions.instructions
            if i isa IR.GlobalGet
                global_ = i.global_
                if global_ isa GlobalBuilder && !(global_ in order)
                    dfs(global_)
                end
            end
        end
        push!(order, gb)
    end

